/**
 * PayPal ISPP 정보
 *
 * ISPP 서비스를 신청하여 엑심베이 및 PayPal의 심사를 통과한 경우 사용합니다.
 * 기본적으로 모든 값이 필수이며, 전송 불가능할 경우 엑심베이에 사전 문의해야 합니다.
 */
export type EximbayV2PaypalIspp = {
    /**
     * 고객사의 구매자 고유 ID
     */
    sender_account_id?: string | undefined;
    /**
     * 구매자 이름
     */
    sender_first_name?: string | undefined;
    /**
     * 구매자 성
     */
    sender_last_name?: string | undefined;
    /**
     * 구매자 이메일
     */
    sender_email?: string | undefined;
    /**
     * 구매자 전화번호
     *
     * [E.123 international format](https://www.itu.int/rec/t-rec-e.123/en) 형식입니다.
     */
    sender_phone?: string | undefined;
    /**
     * 구매자 국가 코드
     *
     * [ISO 3166-1 alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2) 코드입니다.
     */
    sender_country_code?: string | undefined;
    /**
     * 구매자 계정 생성 일자
     *
     * `YYYY-MM-DD HH:mm:ss` 형식으로 입력합니다.
     */
    sender_create_date?: string | undefined;
};
